import numpy as np

grid = np.array(input_grid)

def get_connected_components(grid):
    """Get connected components by color"""
    result = {}
    visited = np.zeros(grid.shape, dtype=bool)

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    for r in range(grid.shape[0]):
        for c in range(grid.shape[1)):
            color = int(grid[r, c])
            if visited[r, c]:
                continue

            component = []
            stack = [(r, c)]
            visited[r, c] = True

            while stack:
                cr, cc = stack.pop()
                component.append((cr, cc))

                for dr, dc in directions:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                        if not visited[nr, nc] and grid[nr, nc] == color:
                            visited[nr, nc] = True
                            stack.append((nr, nc))

            if len(component) > 1:  # Only report non-trivial components
                key = (color, sorted(component))
                result[key] = component

    return result

components = get_connected_components(grid)
print(f"Found {len(components)} components")
for (color, _), comp in sorted(components.items(), key=lambda x: len(x[1]), reverse=True)[:10]:
    print(f"  Color {color}, size {len(comp)}")

