def get_bg_regions():
    visited = set()
    regions = []
    for r in range(25):
        for c in range(27):
            if input_grid[r][c] == 6 and (r,c) not in visited:
                region = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        region.append((cr, cc))
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
