                entry = json.loads(line.strip())
                if 'answer' in entry or 'status' in entry:
                    print(f"Recent status: {entry.get('status', 'unknown')} - {entry.get('answer_preview', '')[:100]}...")
            except:
                pass
else:
    print("Session file not found")
